contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(depositAmt > 0);
        require(collectAmt > depositAmt);
        require(address(this).balance >= depositAmt);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        c.Collect(collectAmt); if (__ESBMC_reverted()) return;
        bool reverted;
        uint balAfter;
        uint ethAfter;
        balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        ethAfter = address(c).balance;
        assert(balAfter == balBefore && ethAfter == ethBefore && address(this).balance == selfBefore);
    }
    receive() external payable {}
}

