pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > depositAmt);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        try c.Collect(collectAmt) {} catch { return; }
        bool reverted;
        uint balAfter;
        uint ethAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        ethAfter = address(c).balance;
        assertTrue(balAfter == balBefore && ethAfter == ethBefore && address(this).balance == selfBefore);
    }

    function testFuzz_run(uint256 depositAmt, uint256 collectAmt) public {
        _run(depositAmt, collectAmt);
    }

    receive() external payable {}
}
